	-- ==============================================================================
	-- Rol sroot (1000): todos los permisos del catalogo Flyway (V2 en adelante), que
	-- quedan fuera del rango de IDs legados 1000-8999 sembrado arriba.
	-- ==============================================================================
	select 1000, p.permiso_id, true from permiso p
	where p.permiso_id not between 1000 and 8999
	  and not exists (select 1 from rol_perm rp where rp.rol_id = 1000 and rp.permiso_id = p.permiso_id);

